"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisLogoCloudContent } from "./components/logo-cloud/content";
import View0 from "./components/logo-cloud/variants/01-marquee";
import View1 from "./components/logo-cloud/variants/02-grid";
import View2 from "./components/logo-cloud/variants/03-columns";
import View3 from "./components/logo-cloud/variants/04-carousel";
const variants = {"marquee":View0,"grid":View1,"columns":View2,"carousel":View3};
export type { ArtemisLogoCloudContent, ArtemisLogoCloudLogo } from "./components/logo-cloud/content";
export interface ArtemisLogoCloudProps { className?: string; variant?: "marquee" | "grid" | "columns" | "carousel"; /** The words on the logo cloud; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisLogoCloudContent>; }
export function ArtemisLogoCloud({ className, variant = "marquee", content }: ArtemisLogoCloudProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}
